/* F · Notas fiscais. G · Financeiro. */
(() => {
const e = v => SP.esc(v), I = (n, s) => SP.icon(n, s), db = () => SP.S.db;
const ST_NF = ['Aguardando envio', 'Enviado', 'Rejeitado', 'Cancelado'];
const optV = () => db().vendedores.map(v => [v.id, v.nome]);
const nfVend = n => SP.pedNum(n.pedido)?.vendedor;
const nfIc = n => `<span class="nf-st t-${SP.TOM[n.status]}">${I({ Enviado: 'check', Rejeitado: 'alert', Cancelado: 'x', 'Aguardando envio': 'clock' }[n.status], 15)}</span>`;
const nfAcoes = n => { const sem = n.status === 'Aguardando envio'; return [sem || n.status === 'Rejeitado' ? { label: sem ? 'Enviar' : 'Corrigir', go: 'nfEmitida', id: n.id, icon: 'send', principal: true } : null, { label: 'Editar', go: 'nfEmitida', id: n.id, icon: 'edit' }, { label: 'PDF (DANFE)', go: 'danfe', id: n.id, icon: 'pdf', disabled: sem }, { label: 'XML', a: 'xml', p: n.id, icon: 'code', disabled: sem }]; };

SP.screen('nfLista', { code: 'F44', nome: 'Notas fiscais', flow: 'F', src: ['print:notas_fiscais', 'proc:Notas fiscais'], nota: 'Totais (faturado, quantidade, canceladas), busca com CFOP e transportadora, PDF, XML, editar e exportar.',
  render(ctx) {
    const barra = SP.filtros(ctx, 'nf', 'Número, cliente ou CNPJ', [{ k: 'numero', label: 'Número da nota (ex.: 339,340)' }, { k: 'doc', label: 'CNPJ/CPF' }, { k: 'cliente', label: 'Cliente' }, { k: 'valor', label: 'Valor' }, { k: 'vendedor', label: 'Vendedor', options: optV() }, { k: 'transp', label: 'Transportadora', options: db().transportadoras.map(t => [t.id, t.nome]) }, { k: 'cfop', label: 'CFOP (um ou mais)', ph: '5102,6102' }, { k: 'unidade', label: 'Unidade (CNPJ emitente)', options: SP.tenant().cnpjs }, { k: 'de', label: 'Data inicial', type: 'date' }, { k: 'ate', label: 'Data final', type: 'date' }]);
    const lst = v => v.split(',').map(s => s.trim()).filter(Boolean);
    const base = SP.filtrar('nf', db().notas, n => n.numero + ' ' + SP.cli(n.cliente).nome + ' ' + SP.cli(n.cliente).cnpj, { numero: (n, v) => lst(v).includes(String(n.numero)), doc: (n, v) => SP.soDig(SP.cli(n.cliente).cnpj).includes(SP.soDig(v)), cliente: (n, v) => SP.contem(SP.cli(n.cliente).nome, v), valor: (n, v) => SP.soDig(n.total.toFixed(2)).includes(SP.soDig(v)), vendedor: (n, v) => nfVend(n) === v, transp: (n, v) => n.transportadora === v, cfop: (n, v) => lst(v).includes(n.cfop), unidade: (n, v) => (SP.pedNum(n.pedido)?.cnpjEmp || SP.tenant().cnpjs[0]) === v, ...SP.periodo(n => n.data) });
    const st = SP.visao('nf'), rows = base.filter(n => st === 'Todos' || n.status === st).sort((a, b) => b.numero - a.numero);
    return { titulo: 'Notas fiscais', acoes: SP.btn('', { a: 'exportar', p: 'nf', icon: 'download', title: 'Exportar planilha' }) + SP.btn(ctx.m ? '' : 'Nova nota fiscal', { go: 'nfNova', id: 'novo', icon: 'plus', kind: 'primary', title: 'Nova nota fiscal' }),
      corpo: `<div class="stats three">${SP.stat('Total faturado', SP.brlk(rows.filter(n => n.status === 'Enviado').reduce((s, n) => s + n.total, 0)))}${SP.stat('Total de notas', rows.length)}${SP.stat('Canceladas', rows.filter(n => n.status === 'Cancelado').length)}</div>` + SP.visoes('nf', ST_NF, n => n.status, base, n => n.total) + barra
        + SP.lista(ctx, { key: 'nf', rows, abrir: n => ({ go: 'nfEmitida', id: n.id }), acoes: nfAcoes, soma: n => n.status === 'Enviado' ? n.total : 0, cols: [{ h: 'Nota', c: n => SP.duas('Nº ' + n.numero, n.tipo + (n.pedido ? ' · pedido ' + n.pedido : '')), s: n => n.numero }, { h: 'Status', c: n => `<span class="row nw">${nfIc(n)}${n.status}</span>`, s: n => n.status }, { h: 'Cliente', c: n => e(SP.cli(n.cliente).nome), s: n => SP.cli(n.cliente).nome }, { h: 'Data', c: n => SP.quando(n.data), s: n => n.data }, { h: 'Transportadora', c: n => e(SP.transp(n.transportadora).nome), s: n => SP.transp(n.transportadora).nome }, { h: 'Total', r: 1, c: n => `<b>${SP.brl(n.total)}</b>`, s: n => n.total }],
          card: n => SP.regLinha(`<span class="row nw">${nfIc(n)}NF ${n.numero}</span>`, SP.brl(n.total), e(SP.cli(n.cliente).nome), `<small class="mute">${n.status} · ${SP.quando(n.data)}</small>`) }) };
  } });

/* ---------- formulário completo da NF-e (abas Geral e Impostos) ---------- */
const O = {
  es: ['0 - Entrada', '1 - Saída'], fin: ['1 - NF-e Normal', '2 - NF-e Complementar', '3 - NF-e de Ajuste', '4 - Devolução'], dest: ['Automático', '1 - Operação interna', '2 - Interestadual', '3 - Exterior'],
  origem: ['0 - Nacional', '1 - Estrangeira, importação direta', '2 - Estrangeira, mercado interno'], cst: ['00 - Tributada integralmente', '20 - Com redução de base', '40 - Isenta', '60 - ICMS cobrado por ST', '102 - Simples sem crédito'], mod: ['0 - Preço tabelado', '4 - Margem de valor agregado', '6 - Valor da operação'],
  ipi: ['00 - Entrada com recuperação', '50 - Saída tributada', '53 - Saída não tributada', '99 - Outras saídas'], pis: ['01 - Operação tributável', '04 - Monofásica', '07 - Isenta', '49 - Outras saídas'], ibs: ['Não informar', '000 - Tributação integral', '010 - Alíquotas uniformes', '200 - Alíquota reduzida'],
};
const IMPOSTOS = [
  ['ICMS', 'icms', [['origem', 'Origem', { options: O.origem }], ['cst', 'CST', { options: O.cst }], ['aliq', 'Alíquota %', { money: true }]]],
  ['ICMS ST', 'icmsst', [['mod', 'Modalidade de determinação', { options: O.mod }], ['aliq', 'Alíquota %', { money: true }]]],
  ['IPI', 'ipi', [['cst', 'CST', { options: O.ipi, vazio: 'Selecione' }], ['enq', 'Código de enquadramento legal'], ['aliq', 'Alíquota %', { money: true }]]],
  ['PIS', 'pis', [['cst', 'CST', { options: O.pis }], ['aliq', 'Alíquota %', { money: true }]]],
  ['COFINS', 'cofins', [['cst', 'CST', { options: O.pis }], ['aliq', 'Alíquota %', { money: true }]]],
  ['IBS e CBS', 'ibs', [['cst', 'CST', { options: O.ibs }], ['classe', 'Classificação tributária (cClassTrib)'], ['aliqUf', 'IBS UF · alíquota %', { money: true }], ['aliq', 'CBS · alíquota %', { money: true }]]],
];
const itemNF = (pid, qtd = 1, valor) => { const p = SP.prod(pid) || {}; return { produto: pid, nome: p.nome || '', cfop: '5102', ncm: p.ncm || '', cest: '', valor: valor ?? p.preco ?? 0, desconto: 0, qtd, frete: 0, vtrib: valor ?? p.preco ?? 0, tributos: 0, ordem: '', icmsBase: 0, icmsAliq: 18, icmsValor: 0 }; };
const rascunhoNF = (n, p) => {
  const cl = SP.cli(n?.cliente || p?.cliente);
  const itens = p ? p.itens.map(i => ({ ...itemNF(i.produto, i.qtd, Math.round(SP.itemTotal(i) / i.qtd * 100) / 100), nome: i.nome, ncm: i.ncm, ordem: p.ocNum })) : n ? [{ ...itemNF('p3', 1, n.total), nome: 'Itens da nota ' + n.numero }] : [];
  return { cnpjEmp: p?.cnpjEmp || SP.tenant().cnpjs[0], vendedor: p?.vendedor || '', es: O.es[1], pedido: p?.numero || '', finalidade: O.fin[0], destino: O.dest[0], estrangeiro: '', refNum: '', refChave: '', final: 'Não',
    cliente: cl.id || '', doc: cl.cnpj || '', nome: cl.id ? cl.nome : '', ie: cl.ie || '', isento: cl.isento || 'Não contribuinte', icmsContrib: cl.icms || '', telefone: cl.telefone || '', cep: p?.cep ?? cl.cep ?? '', endereco: p?.endereco ?? cl.endereco ?? '', numeroEnd: p?.numeroEnd ?? cl.numero ?? '', complemento: '', bairro: p?.bairro ?? cl.bairro ?? '', cidade: cl.cidade || '', uf: cl.uf || '', pais: 'Brasil',
    transportadora: n?.transportadora || '', frete: p?.frete_valor || 0, modalidade: p?.frete || 'CIF', caixas: 1, pesoCaixa: '', pesoLiq: '', pesoBruto: '', forma: p?.forma || 'Boleto', natureza: 'Venda de mercadoria', complementares: '', observacao: '', parcelamento: p?.tabela || '28 dias', itens,
    imp: { icms: { origem: O.origem[0], cst: O.cst[0], aliq: 18 }, icmsst: { mod: O.mod[1], aliq: 0 }, ipi: { cst: '', enq: '999', aliq: 0 }, pis: { cst: O.pis[0], aliq: 0.65 }, cofins: { cst: O.pis[0], aliq: 3 }, ibs: { cst: O.ibs[1], classe: '000001', aliqUf: 0.1, aliq: 0.9 } } };
};
const prodTotal = i => SP.parseNum(i.qtd) * SP.parseNum(i.valor) - SP.parseNum(i.desconto) + SP.parseNum(i.frete);
const baseNF = d => d.itens.reduce((s, i) => s + prodTotal(i), 0) + SP.parseNum(d.frete);
const totalCalc = SP.calcDraft;
SP.calcDraft = (d, nome) => {
  if (!d?.imp) return totalCalc(d, nome);
  if (nome === 'total') return SP.brl(baseNF(d));
  if (nome.startsWith('item.')) return SP.brl(prodTotal(d.itens[+nome.slice(5)]));
  if (nome.startsWith('base.')) return SP.brl(baseNF(d));
  if (nome.startsWith('valor.')) { const k = nome.slice(6), x = d.imp[k]; return SP.brl(baseNF(d) * (SP.parseNum(x.aliq) + SP.parseNum(x.aliqUf || 0)) / 100); }
};
const formNF = (ctx, d, ro, modo) => {
  const n = ctx.m ? 1 : 3, c = (p, l, o = {}) => SP.campo(d, p, l, { ro, ...o });
  const aba = modo || SP.S.tab.nf || 'geral';
  const abas = `<div class="tabs" role="tablist">${[['geral', 'Geral'], ['impostos', 'Impostos']].map(([v, l]) => `<button type="button" role="tab" aria-selected="${aba === v}" class="${aba === v ? 'on' : ''}" ${modo ? `data-go="${v === 'geral' ? 'nfNova' : 'nfImpostos'}" data-id="${ctx.id}"` : `data-a="tab" data-p="nf" data-v="${v}"`}>${l}</button>`).join('')}</div>`;
  if (aba === 'impostos') return abas + IMPOSTOS.map(([t, k, campos], idx) => SP.sec('imp-' + k, t, SP.grade(campos.map(([p, l, o]) => c(`imp.${k}.${p}`, l, o)).join(''), n) + `<dl class="calc"><div><dt>Base de cálculo (automática)</dt><dd data-calc="base.${k}">${SP.calcDraft(d, 'base.' + k)}</dd></div><div><dt>Valor do imposto</dt><dd data-calc="valor.${k}">${SP.calcDraft(d, 'valor.' + k)}</dd></div></dl>`, idx === 0 || !ctx.m)).join('');
  const prods = d.itens.map((i, k) => `<li><div class="reg-t"><b>${k + 1}. ${e(i.nome)}</b>${ro ? '' : SP.btn('', { icon: 'trash', a: 'itemRm', p: k, title: 'Remover', kind: 'quiet', sm: true })}</div><div class="grade g${ctx.m ? 2 : 6}">${[['cfop', 'CFOP'], ['ncm', 'NCM'], ['cest', 'CEST'], ['qtd', 'Quantidade'], ['valor', 'Valor', 1], ['desconto', 'Desconto', 1]].map(([p, l, m]) => c(`itens.${k}.${p}`, l, { money: m })).join('')}</div><details class="forn"><summary>Ordem de compra, frete e tributação</summary><div class="grade g${ctx.m ? 2 : 4}">${c(`itens.${k}.ordem`, 'Ordem de compra')}${c(`itens.${k}.frete`, 'Frete do item', { money: true })}${c(`itens.${k}.vtrib`, 'Valor unit. de tributação', { money: true })}${c(`itens.${k}.tributos`, 'Valor aprox. dos tributos', { money: true })}${c(`itens.${k}.icmsBase`, 'Base de cálculo do ICMS', { money: true })}${c(`itens.${k}.icmsAliq`, 'Alíquota do ICMS %', { money: true })}${c(`itens.${k}.icmsValor`, 'Valor do ICMS', { money: true })}</div></details><div class="reg-t"><small class="mute">Total do item</small><strong data-calc="item.${k}">${SP.brl(prodTotal(i))}</strong></div></li>`).join('');
  return abas
    + SP.sec('nf-op', 'Operação', SP.grade(c('cnpjEmp', 'CNPJ emitente', { options: SP.tenant().cnpjs }) + c('vendedor', 'Vendedor', { options: optV(), vazio: 'Selecione' }) + c('es', 'Entrada/saída', { options: O.es }) + c('pedido', 'Pedido', { hint: ro ? '' : 'Preenche cliente, itens e valores' }) + c('finalidade', 'Finalidade', { options: O.fin }) + c('destino', 'Destino da operação', { options: O.dest }) + c('natureza', 'Natureza da operação') + c('final', 'Consumidor final', { options: ['Não', 'Sim'] }) + c('estrangeiro', 'Código estrangeiro') + c('refNum', 'Nota referenciada (número)') + c('refChave', 'Nota referenciada (chave de acesso)', { span: 2 }), n) + (ro ? '' : SP.btn('Puxar dados do pedido', { a: 'puxarPed', icon: 'cart', sm: true })))
    + SP.sec('nf-dest', 'Destinatário', SP.grade(c('doc', 'CPF/CNPJ') + c('nome', 'Nome/Razão social', { span: 2 }) + c('ie', 'Inscrição estadual') + c('isento', 'Isento IE', { options: ['Não contribuinte', 'Sim', 'Não'] }) + c('icmsContrib', 'Contribuinte do ICMS', { options: ['Sim', 'Não'], vazio: 'Selecione' }) + c('telefone', 'Telefone') + c('cep', 'CEP') + c('endereco', 'Endereço') + c('numeroEnd', 'Número') + c('complemento', 'Complemento') + c('bairro', 'Bairro') + c('cidade', 'Cidade') + c('uf', 'Estado', { options: SP.UFS, vazio: 'Nenhum' }) + c('pais', 'País'), n), !ctx.m, e(d.nome))
    + SP.sec('nf-prod', 'Produtos', (ro ? '' : `<div class="add-p"><select data-addnf aria-label="Adicionar produto"><option value="">Adicionar produto…</option>${db().produtos.map(p => `<option value="${p.id}">${e(p.nome)}</option>`).join('')}</select></div>`) + (prods ? `<ul class="itens-m">${prods}</ul>` : SP.vazio('Sem produtos', 'Adicione um produto ou puxe do pedido.', '', 'box')), true, SP.plural(d.itens.length, 'item', 'itens'))
    + SP.sec('nf-transp', 'Transporte', SP.grade(c('transportadora', 'Transportadora', { options: db().transportadoras.map(t => [t.id, t.nome]), vazio: 'Sem transportadora' }) + c('frete', 'Valor do frete', { money: true }) + c('modalidade', 'Modalidade do frete', { options: ['CIF', 'FOB'], vazio: 'Selecione' }) + c('caixas', 'Número de caixas') + c('pesoCaixa', 'Peso das caixas (kg)', { ph: '0,2' }) + c('pesoLiq', 'Peso líquido (kg)') + c('pesoBruto', 'Peso bruto (kg)'), n), !ctx.m)
    + SP.sec('nf-pag', 'Pagamento e informações', SP.grade(c('forma', 'Forma de pagamento', { options: db().params.formas }) + c('parcelamento', 'Tabela de parcelamento', { options: db().params.parcelamentos }), n) + SP.grade(c('complementares', 'Informações complementares', { type: 'area' }) + c('observacao', 'Observação interna', { type: 'area' }), ctx.m ? 1 : 2), !ctx.m);
};
const novaNF = modo => ctx => {
  const p = ctx.id && ctx.id !== 'novo' ? SP.ped(ctx.id) : null;
  const d = SP.draft(ctx, 'nfNova:' + (p?.id || 'novo'), () => rascunhoNF(null, p));
  return { titulo: 'Nova nota fiscal', sub: d.pedido ? 'Preenchida com o pedido ' + d.pedido : '', voltar: 'nfLista', corpo: SP.passos(['Preencher', 'Validar', 'Autorizar na SEFAZ'], 0) + formNF(ctx, d, false, modo),
    rodape: `<span class="rod-t"><small>Total da nota</small><b data-calc="total">${SP.brl(baseNF(d))}</b></span>` + SP.btn('Voltar', { go: 'nfLista' }) + SP.btn('Salvar rascunho', { a: 'salvarNF', v: 'rascunho' }) + SP.btn('Validar e enviar', { a: 'validarNF', kind: 'primary', icon: 'send' }) };
};
SP.screen('nfNova', { form: true, code: 'F45', nome: 'Nova nota fiscal · Geral', flow: 'F', pai: 'nfLista', exemplo: 'd17150', src: ['print:notas_fiscais_edicao-novo', 'novo:Ação irreversível em duas etapas'], nota: 'Todos os campos do legado. “Validar e enviar” mostra o resumo e as pendências antes de ir à SEFAZ.', render: novaNF(null) });
SP.screen('nfImpostos', { form: true, code: 'F46', nome: 'Nova nota fiscal · Impostos', flow: 'F', pai: 'nfLista', exemplo: 'd17150', src: ['print:notas_fiscais_edicao-novo'], nota: 'ICMS, ICMS ST, IPI, PIS, COFINS e IBS/CBS com base e valor calculados.', render: novaNF('impostos') });
SP.screen('nfEmitida', { code: 'F47', nome: 'Nota emitida e ações', flow: 'F', pai: 'nfLista', exemplo: 'n340', src: ['print:notas_fiscais_edicao-detalhe', 'proc:Emissão nota fiscal'], nota: 'Cancelar, carta de correção, ver PDF e XML, consultar SEFAZ, enviar por e-mail, duplicar e atualizar.',
  render(ctx) {
    const n = SP.nfById(ctx.id) || db().notas[0], p = SP.pedNum(n.pedido), d = SP.draft(ctx, 'nf:' + n.id, () => rascunhoNF(n, p));
    const aut = n.status === 'Enviado', rasc = ['Aguardando envio', 'Rejeitado'].includes(n.status);
    const bar = `<div class="barra-a">${aut ? SP.btn('Carta de correção', { go: 'correcao', id: n.id, icon: 'edit' }) : ''}${rasc ? '' : SP.btn('Ver PDF', { go: 'danfe', id: n.id, icon: 'pdf' }) + SP.btn('Ver XML', { a: 'xml', p: n.id, icon: 'code' })}${SP.btn('Consultar SEFAZ', { a: 'consultarNF', p: n.id, icon: 'search' })}${aut ? SP.btn('Enviar por e-mail', { a: 'emailNF', p: n.id, icon: 'mail' }) : ''}${SP.btn('Duplicar', { a: 'dupNF', p: n.id, icon: 'copy' })}${aut ? SP.btn('Cancelar nota', { a: 'pedirCancelNF', p: n.id, icon: 'x', kind: 'danger' }) : ''}</div>`;
    const head = SP.card(`<div class="nf-h">${nfIc(n)}<div><b>${n.status}</b><h2>Nota ${n.numero}</h2><small>${SP.quando(n.data)} · ${e(SP.cli(n.cliente).nome)} · ${SP.brl(n.total)}</small></div></div>${bar}${n.correcao ? SP.aviso('Correção registrada: ' + e(n.correcao), 'info') : ''}`) + (n.motivo ? SP.aviso('<b>Motivo:</b> ' + e(n.motivo), 'bad') : '');
    const crs = db().contas.filter(c => c.nota === n.numero), cl = SP.cli(n.cliente);
    const itens = SP.card(`<div class="rol-x"><table class="tb mini"><thead><tr><th>Produto</th><th class="r">Qtd</th><th class="r">Total</th></tr></thead><tbody>${d.itens.map(i => `<tr><td>${SP.duas(e(i.nome), 'CFOP ' + e(i.cfop) + ' · NCM ' + e(i.ncm || '—'))}</td><td class="r">${i.qtd}</td><td class="r"><b>${SP.brl(prodTotal(i))}</b></td></tr>`).join('')}</tbody></table></div><dl class="soma"><div class="tt"><dt>Total da nota</dt><dd>${SP.brl(n.total)}</dd></div></dl>`, { title: 'Produtos' });
    const main = rasc ? formNF(ctx, d, false) : itens + SP.card(SP.tempo(ctx, n.id, []), { title: 'Linha do tempo' }) + SP.sec('nf-tudo', 'Todos os campos da nota', formNF(ctx, d, true), false, 'geral e impostos');
    const lado = SP.card(`<div class="reg-t"><b>${e(cl.nome)}</b>${SP.riscoPill(n.cliente)}</div>${SP.kv([['CNPJ/CPF', e(cl.cnpj)], ['E-mail', e(cl.email)]])}`, { title: 'Destinatário' })
      + SP.card((rasc ? '<p class="mute">A chave de acesso é gerada na autorização.</p>' : SP.kv([['Protocolo', '1352600' + n.numero + '4417'], ['Ambiente', 'Produção (simulado)']]) + `<p class="chave" translate="no">${chave(n)}</p>`) + (aut ? SP.campo(d, 'vendedor', 'Vendedor', { options: optV(), vazio: 'Selecione' }) : ''), { title: 'SEFAZ' })
      + SP.card(SP.kv([['Transportadora', e(SP.transp(n.transportadora).nome)], ['Pedido', n.pedido ? `<button type="button" class="lk" data-go="pedVer" data-id="${p?.id}">${n.pedido}</button>` : '—']]), { title: 'Transporte' })
      + (crs.length ? SP.card(`<ul class="mini-itens">${crs.map(x => `<li><button type="button" class="lk" data-go="conta" data-id="${x.id}">${SP.dataCurta(x.vencimento)} · ${SP.brl(x.valor)}</button>${SP.pill(SP.contaStatus(x))}</li>`).join('')}</ul>`, { title: 'Parcelas' }) : '');
    return { titulo: 'Nota fiscal ' + n.numero, voltar: 'nfLista', registro: !ctx.m, corpo: ctx.m ? head + main + lado : SP.registro({ topo: head, main, lado }),
      rodape: SP.btn('Voltar', { go: 'nfLista' }) + (rasc ? SP.btn('Enviar à SEFAZ', { a: 'enviarNF', p: n.id, kind: 'primary', icon: 'send' }) : SP.btn('Atualizar nota', { a: 'atualizarNF', p: n.id, kind: 'primary' })) };
  } });
const chave = n => ('3526 11' + SP.soDig(SP.tenant().cnpjs[0]) + '55001' + String(n.numero).padStart(9, '0') + '1' + String(n.numero * 7919).padStart(8, '0') + '0').replace(/\s/g, '').slice(0, 44).replace(/(\d{4})/g, '$1 ');
SP.screen('danfe', { code: 'F48', nome: 'DANFE (PDF)', flow: 'F', pai: 'nfLista', exemplo: 'n340', src: ['print:notas_fiscais'], nota: 'Visualização ilustrativa do PDF, sem valor fiscal.',
  render(ctx) { const n = SP.nfById(ctx.id), c = SP.cli(n.cliente), t = SP.tenant(); return { titulo: 'DANFE · NF ' + n.numero, voltar: 'nfLista', acoes: SP.btn('Imprimir', { a: 'imprimir', icon: 'download', kind: 'primary' }),
    corpo: `<article class="papel danfe" data-print><header>${SP.logo(t, 'light')}<div><h2>DANFE · NF-e ${n.numero}</h2><small>Protótipo, sem valor fiscal</small></div></header><div class="barras-nf" aria-hidden="true"></div><p class="chave">${chave(n)}</p><div class="papel-g"><p><b>Emitente</b>${e(t.razao)}<br>${e(t.cnpjs[0])}</p><p><b>Destinatário</b>${e(c.nome)}<br>${e(c.cnpj)}</p><p><b>Emissão</b>${SP.quando(n.data)}</p><p><b>Natureza</b>Venda de mercadoria · CFOP ${n.cfop}</p><p><b>Transportadora</b>${e(SP.transp(n.transportadora).nome)}</p><p><b>Situação</b>${n.status}</p></div><p class="papel-t"><b>Valor total da nota ${SP.brl(n.total)}</b></p></article>` }; } });
SP.screen('correcao', { code: 'F49', nome: 'Carta de correção', flow: 'F', pai: 'nfLista', exemplo: 'n340', src: ['print:notas_fiscais_edicao-detalhe'], nota: 'Descrição com no mínimo 15 caracteres.',
  render(ctx) { const n = SP.nfById(ctx.id), d = SP.draft(ctx, 'cce:' + n.id, () => ({ texto: '' })); return { titulo: 'Carta de correção · NF ' + n.numero, voltar: 'nfLista', corpo: SP.card(SP.aviso('A carta não altera valores, impostos nem destinatário.', 'info') + SP.campo(d, 'texto', 'Descrição (mínimo 15 caracteres)', { type: 'area', rows: 5, req: true }), { cls: 'estreito' }), rodape: SP.btn('Voltar', { go: 'nfEmitida', id: n.id }) + SP.btn('Enviar correção', { a: 'enviarCCe', p: n.id, kind: 'primary', icon: 'send' }) }; } });
SP.modals.validarNF = () => { const d = SP.S.draft?.v; if (!d) return null; const falta = [!d.nome && 'nome do destinatário', !d.doc && 'CPF/CNPJ', !d.cep && 'CEP', !d.endereco && 'endereço', !d.numeroEnd && 'número', !d.itens.length && 'ao menos um produto'].filter(Boolean);
  return { titulo: 'Conferir antes de enviar', corpo: (falta.length ? SP.aviso('<b>Falta:</b> ' + falta.join(', '), 'bad') : SP.aviso('Validação sem pendências.', 'ok')) + SP.kv([['Destinatário', e(d.nome)], ['Natureza', e(d.natureza)], ['Itens', d.itens.length], ['Total', `<b>${SP.brl(baseNF(d))}</b>`], ['Depois de autorizar', 'Regras geram boleto e enviam ao cliente']]) + '<p class="mute">A autorização na SEFAZ não pode ser desfeita; só cancelada dentro do prazo legal.</p>', rodape: SP.btn('Voltar', { a: 'fechar' }) + SP.btn('Autorizar nota', { a: 'salvarNF', v: 'autorizar', kind: 'primary', disabled: !!falta.length }) }; };
SP.modals.cancelNF = (data, ctx) => { const n = SP.nfById(data.id), d = SP.draft(ctx, 'cnf:' + n.id, () => ({ motivo: '' })); return { titulo: 'Cancelar NF ' + n.numero, corpo: SP.aviso('Os títulos em aberto desta nota serão estornados.', 'warn') + SP.campo(d, 'motivo', 'Justificativa (mínimo 15 caracteres)', { type: 'area', req: true }), rodape: SP.btn('Voltar', { a: 'fechar' }) + SP.btn('Cancelar nota', { a: 'cancelarNF', p: n.id, kind: 'danger' }) }; };

const PASSOS_SEFAZ = ['Validando o XML', 'Assinando com o certificado', 'Aguardando a SEFAZ'];
SP.modals.sefaz = d => ({ titulo: 'Autorizando a nota…', corpo: `<ol class="andamento" role="status">${PASSOS_SEFAZ.map((t, i) => `<li class="${i < d.passo ? 'feito' : i === d.passo ? 'agora' : ''}"><i>${i < d.passo ? I('check', 13) : ''}</i>${t}</li>`).join('')}</ol><p class="mute">Costuma levar poucos segundos. Não feche a janela.</p>`, rodape: '' });
SP.autorizando = fim => { const passo = i => { if (i >= PASSOS_SEFAZ.length) { fim(); return SP.draw(); } SP.S.modal = { type: 'sefaz', data: { passo: i } }; SP.draw(); setTimeout(() => passo(i + 1), 450); }; passo(0); };

/* ---------- cobrança: envelhecimento, prioridade e régua ---------- */
const FAIXAS = [['A vencer', d => d <= 0], ['1 a 7 dias', d => d >= 1 && d <= 7], ['8 a 30 dias', d => d >= 8 && d <= 30], ['Mais de 30 dias', d => d > 30]];
SP.screen('cobranca', { code: 'F60', nome: 'Cobrança', flow: 'G', src: ['proc:Cobrança', 'visao:Automação', 'novo:Envelhecimento e fila por prioridade'], nota: 'Vencidos por faixa de atraso, o que vence na semana, fila ordenada pelo que vale cobrar primeiro (atraso × valor), mensagem revisável e a régua automática.',
  render(ctx) {
    const ab = db().contas.filter(abertaCR), dias = c => SP.dias(c.vencimento), total = ab.reduce((s, c) => s + c.valor, 0), venc = ab.filter(c => dias(c) > 0), tv = venc.reduce((s, c) => s + c.valor, 0);
    const semana = ab.filter(c => dias(c) <= 0 && dias(c) >= -7);
    const rec = db().contas.filter(c => c.status === 'Quitada' && c.pagamento.slice(0, 7) === SP.HOJE.slice(0, 7)).reduce((s, c) => s + c.valor, 0);
    const prio = c => (Math.max(0, dias(c)) + 1) * c.valor;
    const rows = ab.filter(c => dias(c) > -db().params.proxVenc).sort((a, b) => prio(b) - prio(a));
    const ultimo = c => db().atividade.find(a => a.ref?.[1] === c.id);
    const passo = c => dias(c) > 14 ? 'Ligar para o cliente' : dias(c) > 0 ? 'Cobrar' : 'Lembrar';
    const faixas = FAIXAS.map(([n, f]) => ({ n, l: ab.filter(c => f(dias(c))) }));
    return { titulo: 'Cobrança', sub: venc.length ? `${SP.brl(tv)} vencidos em ${SP.plural(venc.length, 'título', 'títulos')}` : 'Nenhum título vencido', acoes: SP.btn('Régua', { go: 'automacoes', icon: 'bolt' }),
      corpo: `<div class="stats">${SP.stat('Em aberto', SP.brlk(total), SP.plural(ab.length, 'título', 'títulos'))}${SP.stat('Vencido', SP.brlk(tv), total ? Math.round(tv / total * 100) + '% do aberto' : '', { tom: tv ? 'bad' : '' })}${SP.stat('Vence em 7 dias', SP.brlk(semana.reduce((s, c) => s + c.valor, 0)), SP.plural(semana.length, 'título para lembrar', 'títulos para lembrar'))}${SP.stat('Recebido no mês', SP.brlk(rec), 'títulos quitados', { tom: 'ok' })}</div>`
        + SP.card(SP.barrasH(faixas.map(x => ({ n: x.n + ' · ' + x.l.length, v: x.l.reduce((s, c) => s + c.valor, 0) }))), { title: 'Por tempo de atraso' })
        + `<h3>Quem cobrar primeiro</h3>` + SP.lista(ctx, { key: 'cob', rows, abrir: c => ({ go: 'conta', id: c.id }), soma: c => c.valor, acoes: c => [{ label: passo(c) === 'Ligar para o cliente' ? 'Cobrar' : passo(c), a: 'cobrar', p: c.id, icon: 'send', principal: true }, { label: 'Ver boleto', go: 'boleto', id: c.id, icon: 'barcode' }, { label: 'Ver cliente', go: 'cliente', id: c.cliente, icon: 'users' }, { label: 'Quitar…', a: 'quitarUma', p: c.id, icon: 'check' }],
          cols: [{ h: 'Cliente', c: c => SP.duas(e(SP.cli(c.cliente).nome), e(c.titulo)), s: c => SP.cli(c.cliente).nome }, { h: 'Risco', c: c => SP.riscoPill(c.cliente) }, { h: 'Atraso', c: c => dias(c) > 0 ? `<b class="t-bad txt">${SP.diasTxt(dias(c))}</b>` : `<span class="mute">vence ${dias(c) === 0 ? 'hoje' : 'em ' + -dias(c) + ' d'}</span>`, s: dias }, { h: 'Último contato', c: c => `<span class="mute">${ultimo(c) ? SP.quando(ultimo(c).em) : 'nenhum'}</span>` }, { h: 'Valor', r: 1, c: c => `<b>${SP.brl(c.valor)}</b>`, s: c => c.valor }],
          card: c => SP.regLinha(e(SP.cli(c.cliente).nome), SP.brl(c.valor), dias(c) > 0 ? `${dias(c)} dias de atraso` : 'vence ' + SP.data(c.vencimento), SP.riscoPill(c.cliente) + SP.btn(passo(c) === 'Lembrar' ? 'Lembrar' : 'Cobrar', { a: 'cobrar', p: c.id, sm: true })) })
        + SP.card(`<ol class="regua">${[['3 dias antes', 'Lembrete com boleto e Pix', 'r9'], ['1 dia depois', 'Cobrança no tom certo', 'r10'], ['7 dias depois', '2ª via atualizada', 'r10'], ['15 dias depois', 'Ligação de uma pessoa', '']].map(([q, t, r]) => { const x = r && SP.by('regras', r); return `<li><b>${q}</b><span>${t}</span><span class="pill t-${!x ? 'info' : x.nivel === 'executar' ? 'ok' : 'warn'}"><i></i>${!x ? 'Pessoa' : x.nivel === 'executar' ? 'Automático' : 'Pede aprovação'}</span></li>`; }).join('')}</ol>`, { title: 'Régua de cobrança' }) };
  } });
SP.modals.cobrar = (data, ctx) => { const c = SP.conta(data.id), late = SP.dias(c.vencimento) > 0, t = SP.by('templates', late ? 'tp7' : 'tp6'), cl = SP.cli(c.cliente), d = SP.draft(ctx, 'cobrar:' + c.id, () => ({ texto: SP.preencher(t.corpo, { conta: c }) }));
  return { titulo: (late ? 'Cobrar ' : 'Lembrar ') + e(cl.nome), largo: true, corpo: SP.destaque([['Valor', SP.brl(c.valor)], ['Vencimento', SP.data(c.vencimento)], ['Histórico', e(SP.risco(c.cliente).motivo)]]) + SP.campo(d, 'texto', `Mensagem · ${t.canal} para ${e(t.canal === 'WhatsApp' ? cl.whats : cl.email)}`, { type: 'area', rows: 6 }), rodape: SP.btn('Cancelar', { a: 'fechar' }) + SP.btn('Enviar mensagem', { a: 'enviarCobranca', p: c.id, kind: 'primary', icon: 'send' }) }; };

/* ---------- contas a receber ---------- */
const ST_CR = ['Aberta', 'Quitada', 'Vencida', 'Próxima ao vencimento', 'Estornada', 'Falta arquivo'];
const abertaCR = c => !['Quitada', 'Estornada'].includes(c.status);
SP.screen('contas', { code: 'F51', nome: 'Contas a receber', flow: 'G', src: ['print:contasareceber', 'proc:Contas a receber', 'proc:Cobrança'], nota: 'Total, status com valores, busca completa, quitar em massa, gerar e ver boleto, editar e exportar.',
  render(ctx) {
    const barra = SP.filtros(ctx, 'cr', 'Título ou cliente', [{ k: 'valor', label: 'Valor' }, { k: 'titulo', label: 'Título' }, { k: 'cliente', label: 'Cliente' }, { k: 'doc', label: 'CNPJ/CPF' }, { k: 'unidade', label: 'Banco / unidade', options: db().bancos.map(b => [b.id, b.nome]) }, { k: 'de', label: 'Vencimento de', type: 'date' }, { k: 'ate', label: 'Vencimento até', type: 'date' }]);
    const base = SP.filtrar('cr', db().contas, c => c.titulo + ' ' + SP.cli(c.cliente).nome, { valor: (c, v) => SP.soDig(c.valor.toFixed(2)).includes(SP.soDig(v)), titulo: (c, v) => SP.contem(c.titulo, v), cliente: (c, v) => SP.contem(SP.cli(c.cliente).nome, v), doc: (c, v) => SP.soDig(SP.cli(c.cliente).cnpj).includes(SP.soDig(v)), unidade: (c, v) => c.banco === v, ...SP.periodo(c => c.vencimento) });
    const st = SP.visao('cr'), rows = base.filter(c => st === 'Todos' || SP.contaStatus(c) === st).sort((a, b) => a.vencimento.localeCompare(b.vencimento));
    const boleto = c => c.boleto ? SP.btn('Ver boleto', { go: 'boleto', id: c.id, icon: 'barcode', sm: true }) : abertaCR(c) ? SP.btn('Gerar boleto', { a: 'gerarBoleto', p: c.id, sm: true }) : '';
    const acoes = c => [SP.contaStatus(c) === 'Vencida' ? { label: 'Cobrar', a: 'cobrar', p: c.id, icon: 'send', principal: true } : null, c.boleto ? { label: 'Ver boleto', go: 'boleto', id: c.id, icon: 'barcode' } : abertaCR(c) ? { label: 'Gerar boleto', a: 'gerarBoleto', p: c.id, icon: 'barcode' } : null, { label: 'Editar', go: 'conta', id: c.id, icon: 'edit' }, abertaCR(c) ? { label: 'Quitar…', a: 'quitarUma', p: c.id, icon: 'check' } : null];
    return { titulo: 'Contas a receber', sub: 'Total ' + SP.brl(rows.reduce((s, c) => s + c.valor, 0)), acoes: SP.btn(ctx.m ? '' : 'Quitar em massa', { a: 'quitarSel', icon: 'check', title: 'Quitar em massa' }) + SP.btn('', { a: 'exportar', p: 'cr', icon: 'download', title: 'Exportar planilha' }) + SP.btn(ctx.m ? '' : 'Nova conta', { go: 'conta', id: 'novo', icon: 'plus', kind: 'primary', title: 'Nova conta' }),
      corpo: SP.visoes('cr', ST_CR, SP.contaStatus, base, c => c.valor) + barra + SP.lista(ctx, { key: 'cr', rows, select: 'cr', acoes, soma: c => c.valor, massa: SP.btn('Quitar selecionadas', { a: 'quitarSel', sm: true, kind: 'primary', icon: 'check' }), abrir: c => ({ go: 'conta', id: c.id }),
        cols: [{ h: 'Título', c: c => SP.duas(e(c.titulo), e(SP.cli(c.cliente).nome)), s: c => SP.cli(c.cliente).nome }, { h: 'Status', c: c => SP.pill(SP.contaStatus(c)), s: SP.contaStatus }, { h: 'Vencimento', c: c => SP.duas(SP.data(c.vencimento), c.pagamento ? 'pago ' + SP.data(c.pagamento) : abertaCR(c) ? (c.vencimento < SP.HOJE ? `há ${SP.dias(c.vencimento)} dias` : `em ${SP.dias(SP.HOJE, c.vencimento)} dias`) : ''), s: c => c.vencimento }, { h: 'Descrição', c: c => `<span class="mute">${e(c.descricao || (c.pedido ? 'Pedido ' + c.pedido : '—'))}</span>` }, { h: 'Valor', r: 1, c: c => `<b>${SP.brl(c.valor)}</b>`, s: c => c.valor }],
        card: c => SP.regLinha(e(c.titulo), SP.brl(c.valor), e(SP.cli(c.cliente).nome) + ' · vence ' + SP.data(c.vencimento), SP.pill(SP.contaStatus(c)) + boleto(c)) }) };
  } });
SP.cadastro({ key: 'conta', code: 'F52', nome: 'Conta a receber (nova e edição)', flow: 'G', col: 'contas', lista: 'contas', exemplo: 'cr9', src: ['print:contasareceber_edicao-novo', 'print:contasareceber_edicao-detalhe'], nota: 'Status, banco, vencimento, pagamento, título, valor, descrição e anexos.', titulo: ['Nova conta a receber', 'Editar conta a receber'],
  novo: { status: 'Aberta', banco: 'b1', vencimento: '', pagamento: '', titulo: '', valor: 0, cliente: '', descricao: '', anexos: [], boleto: false }, obrig: [['titulo', 'título'], ['vencimento', 'vencimento'], ['cliente', 'cliente']], numericos: ['valor'],
  antes: (reg, ctx) => { const d = SP.draft(ctx, 'conta:' + (ctx.id || 'novo'), () => SP.clone(reg || SP.screens.conta.cad.novo)); return SP.card(`<h4>Status</h4>${SP.radios(d.status, ['Aberta', 'Estornada', 'Falta arquivo', 'Quitada'], 'stDraft', 'status')}<h4>Banco</h4>${SP.seg(d.banco, db().bancos.map(b => [b.id, e(b.nome)]), 'stDraft', 'banco')}`); },
  campos: () => [['vencimento', 'Data de vencimento', { type: 'date', req: true }], ['pagamento', 'Data de pagamento', { type: 'date' }], ['valor', 'Valor (R$)', { money: true }], ['titulo', 'Título', { req: true, span: 2 }], ['cliente', 'Cliente', { options: db().clientes.map(c => [c.id, c.nome]), vazio: 'Selecione', req: true }], ['descricao', 'Descrição', { type: 'area', span: 3 }]],
  extra: (d, ctx) => SP.card(`<h4>Anexos</h4>${SP.anexos(d.anexos, 'anexoDraft', '')}`),
  depois: reg => reg.boleto ? SP.card(`<div class="row">${SP.btn('Ver boleto', { go: 'boleto', id: reg.id, icon: 'barcode' })}${abertaCR(reg) ? SP.btn('Quitar agora', { a: 'quitarUma', p: reg.id, icon: 'check' }) : ''}</div>`) : '' });
const modalQuitar = (data, ctx) => { const ids = data.ids, l = ids.map(SP.conta).filter(c => c && abertaCR(c)), d = SP.draft(ctx, 'quitar', () => ({ banco: 'b1', juros: 0, data: SP.HOJE }));
  return { titulo: 'Quitar contas em massa', corpo: `<ul class="mini-itens">${l.map(c => `<li><span>${e(c.titulo)}<small class="mute"> · ${e(SP.cli(c.cliente).nome)}</small></span><b>${SP.brl(c.valor)}</b></li>`).join('')}<li class="tt"><span>${SP.plural(l.length, 'título', 'títulos')}</span><b>${SP.brl(l.reduce((s, c) => s + c.valor, 0))}</b></li></ul>` + SP.grade(SP.campo(d, 'banco', 'Banco', { options: db().bancos.map(b => [b.id, b.nome]) }) + SP.campo(d, 'juros', 'Juros por título (R$)', { money: true }) + SP.campo(d, 'data', 'Data do pagamento', { type: 'date' }), ctx.m ? 1 : 3), largo: true, rodape: SP.btn('Cancelar', { a: 'fechar' }) + SP.btn('Quitar ' + l.length, { a: 'confirmarQuitar', p: l.map(c => c.id).join(','), kind: 'primary', disabled: !l.length }) }; };
SP.modals.quitar = modalQuitar;
SP.screen('quitar', { code: 'F53', nome: 'Quitar em massa', flow: 'G', pai: 'contas', base: 'contas', modal: { type: 'quitar', data: { ids: ['cr4', 'cr6', 'cr7'] } }, src: ['print:contasareceber', 'novo:Ação em lote com resumo'], nota: 'Resumo antes de confirmar: banco, juros e data. Concluir a última parcela fecha o pedido sozinho.', render: ctx => SP.screens.contas.render(ctx) });

SP.screen('boletos', { code: 'F54', nome: 'Boletos', flow: 'G', src: ['proc:Boletos', 'proc:Emissão boleto'], nota: 'Registro, situação no banco, 2ª via e envio. No legado era uma tela “em construção”.',
  render(ctx) { const sit = c => c.status === 'Quitada' ? 'Quitada' : c.status === 'Estornada' ? 'Estornada' : SP.contaStatus(c); const rows = SP.filtrar('bol', db().contas.filter(c => c.boleto), c => c.titulo + ' ' + SP.cli(c.cliente).nome).sort((a, b) => b.vencimento.localeCompare(a.vencimento)); const sem = db().contas.filter(c => !c.boleto && abertaCR(c));
    return { titulo: 'Boletos', sub: SP.plural(rows.length, 'boleto registrado', 'boletos registrados'), corpo: (sem.length ? SP.aviso(SP.plural(sem.length, 'título aberto sem boleto', 'títulos abertos sem boleto') + '.', 'warn', SP.btn('Gerar todos', { a: 'gerarTodos', sm: true })) : '') + SP.filtros(ctx, 'bol', 'Título ou cliente') + SP.lista(ctx, { key: 'bol', rows, abrir: c => ({ go: 'boleto', id: c.id }), soma: c => c.valor, acoes: c => [{ label: '2ª via', go: 'boleto', id: c.id, principal: true }, { label: 'Enviar ao cliente', a: 'enviarBoleto', p: c.id, icon: 'send' }], cols: [{ h: 'Título', c: c => SP.duas(e(c.titulo), e(SP.cli(c.cliente).nome)), s: c => SP.cli(c.cliente).nome }, { h: 'Situação', c: c => SP.pill(sit(c)), s: sit }, { h: 'Banco', c: c => e(SP.by('bancos', c.banco)?.nome) }, { h: 'Vencimento', c: c => SP.data(c.vencimento), s: c => c.vencimento }, { h: 'Valor', r: 1, c: c => `<b>${SP.brl(c.valor)}</b>`, s: c => c.valor }], card: c => SP.regLinha(e(c.titulo), SP.brl(c.valor), e(SP.cli(c.cliente).nome) + ' · ' + SP.data(c.vencimento), SP.pill(sit(c))) }) }; } });
SP.linhaDigitavel = c => `07790.00116 ${String(c.valor * 100 | 0).padStart(5, '0').slice(-5)}.${String(c.id.length * 123457).slice(0, 6)} 00000.000000 1 ${SP.soDig(c.vencimento).slice(-4)}${String(Math.round(c.valor * 100)).padStart(10, '0')}`;
SP.screen('boleto', { code: 'F55', nome: 'Boleto e Pix', flow: 'G', pai: 'boletos', exemplo: 'cr4', src: ['proc:Boletos', 'print:contasareceber'], nota: 'Linha digitável, Pix, copiar e enviar.',
  render(ctx) { const c = SP.conta(ctx.id), t = SP.tenant(); return { titulo: 'Boleto', sub: e(c.titulo), voltar: 'boletos', acoes: SP.btn(ctx.m ? '' : 'Enviar ao cliente', { a: 'enviarBoleto', p: c.id, icon: 'send', title: 'Enviar ao cliente' }) + SP.btn('Imprimir', { a: 'imprimir', icon: 'download', kind: 'primary' }),
    corpo: `<article class="papel" data-print><header>${SP.logo(t, 'light')}<div><h2>${SP.brl(c.valor)}</h2><small>vence em ${SP.data(c.vencimento)}</small></div></header><div class="papel-g"><p><b>Beneficiário</b>${e(t.razao)}</p><p><b>Pagador</b>${e(SP.cli(c.cliente).nome)}</p><p><b>Título</b>${e(c.titulo)}</p><p><b>Situação</b>${SP.contaStatus(c)}</p></div><p class="chave">${SP.linhaDigitavel(c)}</p><div class="barras-nf" aria-hidden="true"></div><div class="pix">${SP.qr(c.id)}<div><b>Ou pague com Pix</b><small>QR Code ilustrativo</small></div></div></article><div class="row centro">${SP.btn('Copiar linha digitável', { a: 'copiar', v: SP.linhaDigitavel(c), icon: 'copy' })}</div>` }; } });

SP.screen('bancos', { code: 'F56', nome: 'Bancos', flow: 'G', src: ['proc:Bancos', 'print:contasareceber_edicao-novo'], nota: 'Contas usadas em boletos e baixas.',
  render(ctx) { return { titulo: 'Bancos', acoes: SP.btn(ctx.m ? '' : 'Nova conta bancária', { go: 'bancoForm', id: 'novo', icon: 'plus', kind: 'primary', title: 'Nova conta bancária' }), corpo: `<div class="tiles">${db().bancos.map(b => { const ab = db().contas.filter(c => c.banco === b.id && abertaCR(c)); return SP.card(`<div class="reg-t"><b>${e(b.nome)}</b>${b.padrao ? '<span class="pill t-info"><i></i>Padrão</span>' : ''}</div><small class="mute">Banco ${b.banco} · ag. ${b.agencia} · conta ${b.conta}</small><div class="saldo"><span>Saldo</span><b>${SP.brl(b.saldo)}</b></div><div class="saldo"><span>A receber</span><b>${SP.brl(ab.reduce((s, c) => s + c.valor, 0))}</b></div><div class="row">${SP.btn('Editar', { go: 'bancoForm', id: b.id, sm: true })}<span class="pill t-${b.integrado ? 'ok' : 'warn'}"><i></i>${b.integrado ? 'Baixa automática' : 'Baixa manual'}</span></div>`); }).join('')}</div>` }; } });
SP.cadastro({ key: 'bancoForm', code: 'F59', nome: 'Cadastro de conta bancária', flow: 'G', col: 'bancos', lista: 'bancos', exemplo: 'b1', src: ['proc:Bancos'], nota: 'Dados da conta usada para registrar boletos.', titulo: ['Nova conta bancária', 'Editar conta bancária'], novo: { nome: '', banco: '', agencia: '', conta: '', padrao: false, integrado: false, saldo: 0 },
  campos: () => [['nome', 'Apelido', { req: true }], ['banco', 'Código do banco'], ['agencia', 'Agência'], ['conta', 'Conta'], ['saldo', 'Saldo inicial', { money: true }]], numericos: ['saldo'] });

/* ---------- faturamento ---------- */
const linhasFat = q => { const nfs = db().notas.filter(n => n.status === 'Enviado' && (!q.de || n.data.slice(0, 10) >= q.de) && (!q.ate || n.data.slice(0, 10) <= q.ate) && (!q.unidade || (SP.pedNum(n.pedido)?.cnpjEmp || SP.tenant().cnpjs[0]) === q.unidade));
  return db().vendedores.filter(v => !q.vendedor || v.id === q.vendedor).map(v => { const l = nfs.filter(n => nfVend(n) === v.id); return { v, notas: l, total: l.reduce((s, n) => s + n.total, 0) }; }).filter(x => x.notas.length).sort((a, b) => b.total - a.total); };
SP.screen('faturamento', { code: 'F57', nome: 'Faturamento', flow: 'G', src: ['print:faturamento', 'proc:Faturamento', 'visao:Investidor'], nota: 'Por vendedor e período, com unidade, total e exportação em planilha ou PDF.',
  render(ctx) { if (!SP.S.q.fat) SP.S.q.fat = { de: '2026-11-01' }; const q = SP.S.q.fat, l = linhasFat(q), tot = l.reduce((s, x) => s + x.total, 0);
    const f = (k, label, o) => `<label class="f"><span>${label}</span>${o.options ? `<select data-q="fat.${k}"><option value="">${o.vazio}</option>${o.options.map(([v, n]) => `<option value="${v}"${q[k] === v ? ' selected' : ''}>${e(n)}</option>`).join('')}</select>` : `<input type="date" data-q="fat.${k}" value="${q[k] || ''}">`}</label>`;
    return { titulo: 'Faturamento', sub: 'Notas autorizadas no período', acoes: SP.btn(ctx.m ? '' : 'Excel', { a: 'exportar', p: 'fat', icon: 'download', title: 'Exportar Excel' }) + SP.btn(ctx.m ? '' : 'PDF', { a: 'imprimir', icon: 'pdf', title: 'Exportar PDF' }),
      corpo: SP.card(SP.grade(f('vendedor', 'Vendedor', { options: optV(), vazio: 'Todos' }) + f('de', 'Data inicial', {}) + f('ate', 'Data final', {}) + f('unidade', 'Unidade', { options: SP.tenant().cnpjs.map(c => [c, c]), vazio: 'Todas' }), ctx.m ? 2 : 4))
        + `<div data-print class="pilha"><div class="stats three">${SP.stat('Faturamento do período', SP.brl(tot))}${SP.stat('Notas', l.reduce((s, x) => s + x.notas.length, 0))}${SP.stat('Ticket médio', SP.brl(tot / (l.reduce((s, x) => s + x.notas.length, 0) || 1)))}</div>`
        + (l.length ? SP.card(SP.barrasH(l.map(x => ({ n: x.v.nome, v: x.total }))), { title: 'Por vendedor' }) + SP.card(`<table class="tb mini"><thead><tr><th>Vendedor</th><th>Notas</th><th class="r">Faturamento</th></tr></thead><tbody>${l.map(x => `<tr><td>${e(x.v.nome)}</td><td>${x.notas.map(n => n.numero).join(', ')}</td><td class="r"><b>${SP.brl(x.total)}</b></td></tr>`).join('')}<tr class="tt"><td>Total</td><td></td><td class="r"><b>${SP.brl(tot)}</b></td></tr></tbody></table>`) : SP.vazio('Sem faturamento no período', 'Mude as datas ou o vendedor.', '', 'chart')) + '</div>' };
  } });

SP.graficoFluxo = (ctx, fim) => { const m = db().faturamentoMes.slice(0, fim + 1).slice(ctx.m ? -8 : -12); return SP.grafLinha(ctx, m.map(x => x[0]), [{ nome: 'Realizado', cls: 's1', dados: m.map(x => x[2]) }, { nome: 'Previsto', cls: 's2', dados: m.map(x => x[1]) }]); };
SP.screen('fluxoPrev', { code: 'F58', nome: 'Fluxo previsto', flow: 'G', src: ['print:fluxo_previsto', 'novo:Previsão a partir dos títulos'], nota: 'Previsto × realizado por mês, com dica ao passar o mouse, tabela e as próximas entradas já contratadas.',
  render(ctx) {
    const m = db().faturamentoMes, sel = SP.S.tab.mes ?? String(m.length - 1), i = +sel, [rot, prev, real] = m[i], tabela = SP.S.tab.fluxoV === 'tab';
    const semanas = [0, 1, 2, 3, 4, 5].map(k => { const a = SP.addDias(SP.HOJE, k * 7), b = SP.addDias(a, 6); return { n: SP.dataCurta(a) + ' a ' + SP.dataCurta(b), v: db().contas.filter(c => abertaCR(c) && c.vencimento >= a && c.vencimento <= b).reduce((s, c) => s + c.valor, 0) }; });
    return { titulo: 'Fluxo previsto · ' + rot, acoes: `<select data-tabsel="mes" aria-label="Mês">${m.map((x, k) => `<option value="${k}"${k === i ? ' selected' : ''}>${x[0]}</option>`).join('')}</select>`,
      corpo: `<div class="stats three">${SP.stat('Previsto no mês', SP.brlk(prev))}${SP.stat('Realizado', SP.brlk(real), rot === 'Nov/26' ? 'mês em andamento' : '')}${SP.stat('Diferença', (real >= prev ? '+' : '−') + SP.brlk(Math.abs(real - prev)), Math.round(real / prev * 100) + '% do previsto', { tom: real >= prev ? 'ok' : 'warn' })}</div>`
        + SP.card(tabela ? `<table class="tb mini"><thead><tr><th>Mês</th><th class="r">Previsto</th><th class="r">Realizado</th></tr></thead><tbody>${m.slice(0, i + 1).map(x => `<tr><td>${x[0]}</td><td class="r">${SP.brl(x[1])}</td><td class="r">${SP.brl(x[2])}</td></tr>`).join('')}</tbody></table>` : (i > 0 ? SP.graficoFluxo(ctx, i) : SP.vazio('Escolha um mês com histórico', '', '', 'line')), { title: 'Faturamento por mês', actions: SP.seg(tabela ? 'tab' : 'graf', [['graf', 'Gráfico'], ['tab', 'Tabela']], 'tab', 'fluxoV') })
        + SP.card(SP.barrasH(semanas), { title: 'Entradas contratadas nas próximas 6 semanas' }) };
  } });

/* ---------- ações ---------- */
const exportar = {
  orc: () => [['Número', 'Data', 'Status', 'Cliente', 'Vendedor', 'Total'], ...db().orcamentos.map(o => [o.numero, SP.data(o.data), o.status, SP.cli(o.cliente).nome, SP.vend(o.vendedor).nome, SP.num(SP.total(o))])],
  ped: () => [['Número', 'Data', 'Status', 'Etapa', 'Cliente', 'Vendedor', 'Total'], ...db().pedidos.map(p => [p.numero, SP.data(p.data), p.status, SP.rotulo(p), SP.cli(p.cliente).nome, SP.vend(p.vendedor).nome, SP.num(SP.total(p))])],
  nf: () => [['Número', 'Data', 'Status', 'Cliente', 'Transportadora', 'Total'], ...db().notas.map(n => [n.numero, SP.data(n.data), n.status, SP.cli(n.cliente).nome, SP.transp(n.transportadora).nome, SP.num(n.total)])],
  cr: () => [['Status', 'Vencimento', 'Pagamento', 'Título', 'Cliente', 'Valor'], ...db().contas.map(c => [SP.contaStatus(c), SP.data(c.vencimento), SP.data(c.pagamento), c.titulo, SP.cli(c.cliente).nome, SP.num(c.valor)])],
  fat: () => [['Vendedor', 'Notas', 'Faturamento'], ...linhasFat(SP.S.q.fat || {}).map(x => [x.v.nome, x.notas.map(n => n.numero).join(', '), SP.num(x.total)])],
};
const xml = n => `<?xml version="1.0" encoding="UTF-8"?>\n<!-- Protótipo, sem valor fiscal -->\n<nfeProc><NFe><infNFe>\n  <ide><nNF>${n.numero}</nNF><dhEmi>${n.data}</dhEmi></ide>\n  <emit><CNPJ>${SP.soDig(SP.tenant().cnpjs[0])}</CNPJ><xNome>${e(SP.tenant().razao)}</xNome></emit>\n  <dest><CNPJ>${SP.soDig(SP.cli(n.cliente).cnpj)}</CNPJ><xNome>${e(SP.cli(n.cliente).nome)}</xNome></dest>\n  <total><vNF>${n.total.toFixed(2)}</vNF></total>\n</infNFe></NFe></nfeProc>`;
const novaNota = status => { const d = SP.S.draft.v, p = SP.pedNum(+d.pedido); let c = d.cliente || db().clientes.find(x => x.cnpj === d.doc)?.id || ''; const n = { id: SP.uid('n'), numero: SP.prox('notas'), data: SP.agora(), status, cliente: c, pedido: p?.numero || null, total: Math.round(baseNF(d) * 100) / 100, transportadora: d.transportadora, tipo: d.es, cfop: d.itens[0]?.cfop || '5102' }; db().notas.unshift(n); return { n, p }; };
Object.assign(SP.actions, {
  exportar: el => { const k = el.dataset.p; SP.baixar(k + '-' + SP.HOJE + '.csv', SP.csv(exportar[k]()), 'text/csv'); SP.toast('Planilha exportada.'); },
  xml: el => { const n = SP.nfById(el.dataset.p); SP.baixar('nfe-' + n.numero + '.xml', xml(n), 'application/xml'); SP.toast('XML baixado.'); },
  puxarPed: () => { const d = SP.S.draft.v, p = SP.pedNum(+d.pedido); if (!p) return SP.toast('Pedido não encontrado.'); Object.assign(d, rascunhoNF(null, p)); },
  validarNF: () => { SP.S.modal = { type: 'validarNF' }; },
  salvarNF: el => { const aut = el.dataset.v === 'autorizar', fazer = () => { let id; SP.feito(aut ? 'Nota autorizada. Regras executadas.' : 'Rascunho salvo.', () => { const { n, p } = novaNota(aut ? 'Enviado' : 'Aguardando envio'); id = n.id; if (aut) { if (p) { p.nf = true; p.status = 'Faturado'; p.atualizado = SP.HOJE; db().fila.filter(f => f.ref[1] === p.id && ['nf', 'dados'].includes(f.tipo)).forEach(f => f.status = 'resolvido'); } SP.log('', 'NF ' + n.numero + ' emitida', ['nf', n.id], 'pessoa'); SP.nfAutorizada(n, p); } }); if (aut) SP.S.undo = null, SP.S.toast.undo = false; SP.S.modal = null; SP.S.draft = null; SP.ir('nfEmitida', id); }; aut ? SP.autorizando(fazer) : fazer(); },
  enviarNF: el => { const idNota = el.dataset.p; SP.autorizando(() => { SP.feito('Nota autorizada.', () => { const n = SP.nfById(idNota), p = SP.pedNum(n.pedido); n.status = 'Enviado'; n.data = SP.agora(); delete n.motivo; if (p) { p.nf = true; p.status = 'Faturado'; } SP.log('', 'NF ' + n.numero + ' emitida', ['nf', n.id], 'pessoa'); SP.nfAutorizada(n, p); }); SP.S.modal = null; SP.S.undo = null; SP.S.toast.undo = false; SP.S.draft = null; }); },
  consultarNF: el => { const n = SP.nfById(el.dataset.p); SP.toast(`SEFAZ: NF ${n.numero} · ${n.status === 'Enviado' ? '100 · Autorizado o uso' : n.status === 'Cancelado' ? '101 · Cancelamento homologado' : 'ainda não autorizada'}.`); },
  emailNF: el => SP.feito('PDF e XML enviados ao cliente.', () => SP.log('', 'NF ' + SP.nfById(el.dataset.p).numero + ' enviada por e-mail', ['nf', el.dataset.p], 'pessoa')),
  dupNF: el => { let id; SP.feito('Nota duplicada como rascunho.', () => { const c = SP.clone(SP.nfById(el.dataset.p)); Object.assign(c, { id: id = SP.uid('n'), numero: SP.prox('notas'), data: SP.agora(), status: 'Aguardando envio', pedido: null }); delete c.motivo; delete c.correcao; db().notas.unshift(c); }); SP.ir('nfEmitida', id); },
  atualizarNF: el => { SP.feito('Nota atualizada.', () => { const n = SP.nfById(el.dataset.p), p = SP.pedNum(n.pedido); if (p && SP.S.draft.v.vendedor) p.vendedor = SP.S.draft.v.vendedor; }); },
  pedirCancelNF: el => { SP.S.modal = { type: 'cancelNF', data: { id: el.dataset.p } }; },
  cancelarNF: el => { const m = SP.S.mdraft.v.motivo.trim(); if (m.length < 15) { SP.S.erros = { motivo: `A justificativa precisa de 15 caracteres ou mais (faltam ${15 - m.length}).` }; return; } SP.feito('Nota cancelada.', () => { const n = SP.nfById(el.dataset.p); n.status = 'Cancelado'; n.motivo = m; db().contas.filter(c => c.nota === n.numero && c.status === 'Aberta').forEach(c => c.status = 'Estornada'); const p = SP.pedNum(n.pedido); if (p) { p.nf = false; p.boleto = false; p.status = 'Aprovado'; } SP.log('', 'NF ' + n.numero + ' cancelada: ' + m, ['nf', n.id], 'pessoa'); }); SP.S.undo = null; SP.S.toast.undo = false; SP.S.modal = null; SP.S.draft = null; },
  enviarCCe: el => { if (!SP.validar(SP.S.draft.v, { texto: { req: true, min: 15, label: 'a descrição' } })) return; const t = SP.S.draft.v.texto.trim(); SP.feito('Carta de correção enviada.', () => { const n = SP.nfById(el.dataset.p); n.correcao = t; SP.log('', 'Carta de correção da NF ' + n.numero, ['nf', n.id], 'pessoa'); }); SP.S.draft = null; SP.ir('nfEmitida', el.dataset.p); },
  cobrar: el => { SP.S.pop = null; SP.S.modal = { type: 'cobrar', data: { id: el.dataset.p } }; SP.S.mdraft = null; },
  enviarCobranca: el => { SP.feito('Mensagem enviada ao cliente.', () => { const c = SP.conta(el.dataset.p); SP.log('', 'Cobrança enviada: ' + c.titulo, ['conta', c.id], 'pessoa'); SP.S.db.fila.filter(f => f.ref[1] === c.id).forEach(f => f.status = 'resolvido'); }); SP.S.modal = null; SP.S.mdraft = null; },
  quitarSel: () => { const sel = (SP.S.sel.cr || []).filter(id => SP.conta(id) && abertaCR(SP.conta(id))); if (!sel.length) return SP.toast('Selecione os títulos em aberto na lista.'); SP.S.modal = { type: 'quitar', data: { ids: sel } }; SP.S.mdraft = null; },
  quitarUma: el => { SP.S.modal = { type: 'quitar', data: { ids: [el.dataset.p] } }; SP.S.mdraft = null; },
  confirmarQuitar: el => { const d = SP.S.mdraft.v, ids = el.dataset.p.split(','); SP.feito(SP.plural(ids.length, 'título quitado.', 'títulos quitados.'), () => SP.quitar(ids, d.data, d.banco, SP.parseNum(d.juros))); SP.S.modal = null; SP.S.mdraft = null; SP.S.draft = null; SP.S.sel.cr = []; SP.fecharTela(); },
  gerarBoleto: el => SP.feito('Boleto registrado no banco.', () => { const c = SP.conta(el.dataset.p); c.boleto = true; SP.log('', 'Boleto gerado: ' + c.titulo, ['conta', c.id], 'pessoa'); }),
  gerarTodos: () => SP.feito('Boletos gerados.', () => db().contas.filter(c => !c.boleto && abertaCR(c)).forEach(c => c.boleto = true)),
  enviarBoleto: el => SP.feito('Boleto enviado ao cliente.', () => { const c = SP.conta(el.dataset.p); SP.log('', 'Boleto enviado: ' + c.titulo, ['conta', c.id], 'pessoa'); }),
});
})();
